            if dot_seen or comma_seen:
                raise ValueError("invalid value")
            dot_seen = True
        elif ch == ',':
            if comma_seen or dot_seen:
                raise ValueError("invalid value")
            comma_seen = True
    if s[0] in '+-':
        raise ValueError("invalid value")
    if comma_seen or dot_seen:
        if s.startswith('-') or s.endswith('-'):
            raise ValueError("invalid value")
        num = float(s.replace(',', '.'))
        if num != num or num in (float("inf"), float("-inf"), float("nan")):
